$renderedProductIds = [];
$section=static function(string $label,string $title,array $products)use($card,$publicPath,&$renderedProductIds):void{
    $unique = [];
    foreach ($products as $product) {
        $id = (int)($product['id'] ?? 0);
        if ($id > 0 && !isset($renderedProductIds[$id])) {
            $renderedProductIds[$id] = true;
            $unique[] = $product;
        }
    }
    if(!$unique)return;
    echo '<section class="store-section"><div class="section-head"><div><p class="eyebrow">'.e($label).'</p><h2>'.e($title).'</h2></div><a class="text-link" href="'.e($publicPath.'/store').'">View all </a></div><div class="product-grid-premium">';
    foreach($unique as $product)$card($product);
    echo '</div></section>';
};
